// A requested observation belongs to an engine version. The solver only writes
// into the explicitly supplied trace, never global state or lazy history replay.
pub(crate) struct CollisionTrace {
    pub frame: i32,
    pub count: usize,
    pub points: [f64; ITERATE * NENT * 6],
}

impl CollisionTrace {
    pub(crate) fn new(frame: i32) -> Self {
        Self { frame, count: 0, points: [0.0; ITERATE * NENT * 6] }
    }
    pub(crate) fn reset(&mut self, frame: i32) {
        self.frame = frame;
        self.count = 0;
    }
    #[cold]
    #[inline(never)]
    fn record(&mut self, s: &State, iteration: usize) {
        for i in 0..NENT {
            let k = (iteration * NENT + i) * 6;
            self.points[k] = s.px[i]; self.points[k + 1] = s.py[i];
            self.points[k + 2] = s.prevx[i]; self.points[k + 3] = s.prevy[i];
            self.points[k + 4] = s.vx[i]; self.points[k + 5] = s.vy[i];
        }
        self.count = iteration + 1;
    }
}

#[derive(Default)]
struct DirectionShadow { valid:bool, seen:bool, bounds:[f64;4], filtered:Vec<*const Line>, previous:Vec<*const Line> }
thread_local! { static DIRECTION_COUNTS: std::cell::RefCell<[u64;9]> = const { std::cell::RefCell::new([0;9]) }; }
fn count_direction(query:&[*const Line], actual:&[*const Line], shadow:&mut DirectionShadow,vx:f64,vy:f64){
    let mut count=[0u64;9];count[0]=1;count[1]=query.len() as u64;
    if shadow.seen && shadow.previous==actual {count[2]=1;count[3]=query.len() as u64;}
    shadow.seen=true;shadow.previous.clear();shadow.previous.extend_from_slice(actual);
    if shadow.valid && vx>=shadow.bounds[0] && vx<=shadow.bounds[1] && vy>=shadow.bounds[2] && vy<=shadow.bounds[3] {
        assert_eq!(shadow.filtered,actual,"certified direction range mismatch");
        count[4]=1;count[5]=query.len() as u64;
    }else{
        shadow.valid=false;
        let bounds=[vx-0.25,vx+0.25,vy-0.25,vy+0.25];
        let mut valid=bounds.iter().all(|v|v.is_finite());
        if valid {
            for &ptr in query {
                let l=unsafe{&*ptr};
                let (x0,x1)=if l.normx>=0.0{(bounds[0],bounds[1])}else{(bounds[1],bounds[0])};
                let (y0,y1)=if l.normy>=0.0{(bounds[2],bounds[3])}else{(bounds[3],bounds[2])};
                let low=l.normx*x0+l.normy*y0;let high=l.normx*x1+l.normy*y1;
                count[6]+=2;
                if !low.is_finite() || !high.is_finite() || (low>0.0)!=(high>0.0){valid=false;break;}
            }
        }
        if valid {shadow.valid=true;shadow.bounds=bounds;shadow.filtered.clear();shadow.filtered.extend_from_slice(actual);count[7]=1;}else{count[8]=1;}
    }
    DIRECTION_COUNTS.with_borrow_mut(|totals|for i in 0..9{totals[i]+=count[i];});
}
pub(crate) fn direction_count(index:usize)->f64{DIRECTION_COUNTS.with_borrow(|c|c[index] as f64)}

